const HtmlWebpackInlineSourcePlugin = require('html-webpack-inline-source-plugin');
const HtmlWebpackPlugin = require('html-webpack-plugin');
const path = require('path');

module.exports = (env, argv) => ({
  mode: argv.mode === 'production' ? 'production' : 'development',

  // This is necessary because Figma's 'eval' works differently than normal eval
  devtool: argv.mode === 'production' ? false : 'inline-source-map',

  entry: {
    ui: './src/app/index.tsx', // The entry point for your UI code
    code: './src/plugin/controller.ts', // The entry point for your plugin code
  },

  module: {
    rules: [
      // Converts TypeScript code to JavaScript
      { test: /\.tsx?$/, use: 'ts-loader', exclude: /node_modules/ },

      // Enables including CSS by doing "import './file.css'" in your TypeScript code
      {
        test: /\.css$/,
        loader: [{ loader: 'style-loader' }, { loader: 'css-loader' }],
      },

      // Allows you to use "<%= require('./file.svg') %>" in your HTML code to get a data URI
      { test: /\.(png|jpg|gif|webp|svg)$/, loader: [{ loader: 'url-loader' }] },
    ],
  },

  // Webpack tries these extensions for you if you omit the extension like "import './file'"
  resolve: { extensions: ['.tsx', '.ts', '.jsx', '.js'] },

  output: {
    filename: '[name].js',
    path: path.resolve(__dirname, 'dist'), // Compile into a folder called "dist"
  },

  // Tells Webpack to generate "ui.html" and to inline "ui.ts" into it
  plugins: [
    new HtmlWebpackPlugin({
      template: './src/app/index.html',
      filename: 'ui.html',
      inlineSource: '.(js)$',
      chunks: ['ui'],
    }),
    new HtmlWebpackInlineSourcePlugin(),
  ],
});

import React from 'react';
import ReactDOM from 'react-dom';
import App from './components/App';

ReactDOM.render(<App />, document.getElementById('react-page'));

import { StateWithEvent } from '../app/components/XstateChecker';

figma.showUI(__html__);

type Message = {
  type: 'create-states';
  states: StateWithEvent[];
};

figma.ui.onmessage = async (msg: Message) => {
  await figma.loadFontAsync({ family: 'Roboto', style: 'Regular' });
  if (msg.type === 'create-states') {
    const nodes = [];

    msg.states
      .sort((a, b) => {
        if (a.isInitial) {
          return -1;
        }
        return a.events.length > b.events.length ? -1 : 1;
      })
      .forEach((state, i) => {
        const frame = figma.createFrame();
        frame.x = 1064 * i;
        frame.name = state.name;
        frame.resize(1024, 768);

        state.events.forEach((event, index) => {
          const button = figma.createRectangle();
          button.resize(40 + event.type.length * 10, 60);
          button.fills = [{ type: 'SOLID', color: { b: 1, g: 0.3, r: 0.3 } }];

          button.x = 20;
          button.y = 80 * index + 20;

          const title = figma.createText();

          title.characters = event.type;
          title.fontSize = 16;
          title.fills = [{ type: 'SOLID', color: { b: 1, g: 1, r: 1 } }];
          title.resize(40 + event.type.length * 10, 60);
          title.textAlignVertical = 'CENTER';
          title.textAlignHorizontal = 'CENTER';
          title.x = 20;
          title.y = 80 * index + 20;

          frame.appendChild(button);
          frame.appendChild(title);
        });

        figma.currentPage.appendChild(frame);
        nodes.push(frame);
      });

    figma.currentPage.selection = nodes;
    figma.viewport.scrollAndZoomIntoView(nodes);

    // This is how figma responds back to the ui
    figma.ui.postMessage({
      type: 'create-states',
      message: `Created States`,
    });
  }

  figma.closePlugin();
};

import React, { useEffect, useState } from 'react';
import '../styles/ui.css';
import { XStateChecker, StateWithEvent } from './XstateChecker';

const App: React.FC = () => {
  const [states, setStates] = useState<StateWithEvent[]>([]);
  const onCreate = () => {
    parent.postMessage(
      { pluginMessage: { type: 'create-states', states } },
      '*',
    );
  };

  const onCancel = () => {
    parent.postMessage({ pluginMessage: { type: 'cancel' } }, '*');
  };

  useEffect(() => {
    // This is how we read messages sent from the plugin controller
    window.onmessage = (event) => {
      const { type, message } = event.data.pluginMessage;
      if (type === 'create-states') {
        console.log(`Figma Says: ${message}`);
      }
    };
  }, []);

  return (
    <div>
      <h2>Import XState to Figma</h2>
      <XStateChecker
        onChange={(value) => {
          setStates(value.states);
        }}
      />
      <div style={{ marginTop: 16 }}>
        <button id="create" onClick={onCreate}>
          Create
        </button>
        <button onClick={onCancel}>Cancel</button>
      </div>
    </div>
  );
};

export default App;

import * as XState from 'xstate';
import { assign, interpret, Machine, send, spawn, StateNode } from 'xstate';
import { raise } from 'xstate/lib/actions';

export function toMachine(machine: StateNode<any> | string): StateNode<any> {
  if (typeof machine !== 'string') {
    return machine;
  }

  let createMachine: Function;
  try {
    createMachine = new Function(
      'Machine',
      'interpret',
      'assign',
      'send',
      'sendParent',
      'spawn',
      'raise',
      'actions',
      'XState',
      machine,
    );
  } catch (e) {
    throw e;
  }

  const machines: Array<StateNode<any>> = [];

  const machineProxy = (config: any, options: any) => {
    const machine = Machine(config, options);
    machines.push(machine);
    return machine;
  };

  try {
    createMachine(
      machineProxy,
      interpret,
      assign,
      send,
      XState.sendParent,
      spawn,
      raise,
      XState.actions,
      XState,
    );
  } catch (e) {
    throw e;
  }

  return machines[machines.length - 1]! as StateNode<any>;
}

export const fetchMachine = `
// Available variables:
// - Machine
// - interpret
// - assign
// - send
// - sendParent
// - spawn
// - raise
// - actions
// - XState (all XState exports)

const fetchMachine = Machine({
  id: 'fetch',
  initial: 'idle',
  states: {
    idle: {
      on: {
        FETCH: 'loading'
      }
    },
    loading: {
      on: {
        RESOLVE: 'success',
        REJECT: 'failure'
      }
    },
    success: {
      type: 'final'
    },
    errored: {
      type: 'final'
    },
    failure: {
      on: {
        RETRY: {
          target: 'loading',
        },
        RETRY_TOO_OFTEN: 'errored'
      }
    }
  }
});
`;

import AceEditor from 'react-ace';
import 'brace/mode/javascript';
import 'brace/theme/monokai';
import React, { useEffect, useState } from 'react';
import { fetchMachine } from './fetchMachine';
import { toMachine } from './toMachine';

export interface StateWithEvent {
  name: string;
  isInitial: boolean;
  events: {
    type: string;
    target: string;
  }[];
}

export const XStateChecker: React.FC<{
  onChange: (params: { states: StateWithEvent[]; isValid: boolean }) => void;
}> = ({ onChange }) => {
  const [code, setCode] = useState(fetchMachine);

  const checkIfTheStateMachineIsValid = (c: string) => {
    try {
      const machine = toMachine(c);

      const result: StateWithEvent[] = Object.keys(machine.states).map(
        (key) => {
          const state = machine.states[key];
          return {
            name: key,
            isInitial: machine.initial === key,
            events: state.events.map((event) => {
              const nextState = machine.transition(key, event);
              return {
                type: event,
                target: nextState.value as string,
              };
            }),
          };
        },
      );
      onChange({ states: result, isValid: true });
    } catch (e) {
      onChange({ states: [], isValid: false });
    }
  };

  useEffect(() => {
    checkIfTheStateMachineIsValid(code);
  }, [code]);

  return (
    <AceEditor
      mode={'javascript'}
      theme="monokai"
      editorProps={{ $blockScrolling: true }}
      value={code}
      onChange={(value) => setCode(value)}
      setOptions={{ tabSize: 2, fontSize: '12px' }}
      width="100%"
      height={'90px'}
      showGutter={false}
      wrapEnabled
    />
  );
};
